import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { getProperties, searchProperties, deleteProperty } from './apiService';
import PropertyCard from '../src/PropertyCard';
import SearchFilter from '../src/SearchFilter';

const PropertyList = ({ onNavigate }) => {
  const [properties, setProperties] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    // Make sure we're using the correct endpoint for ALL properties
    const fetchProperties = async () => {
      try {
        setLoading(true);
        // This calls /api/properties without any ID parameter
        const response = await axios.get('http://localhost:5001/api/properties');
        setProperties(response.data);
        setLoading(false);
      } catch (err) {
        console.error('Error fetching properties:', err);
        setError('Failed to load properties');
        setLoading(false);
      }
    };

    fetchProperties();
  }, []);


  const loadProperties = async (filters = {}) => {
    setLoading(true);
    try {
      let data;
      if (Object.keys(filters).length > 0) {
        data = await searchProperties(filters);
      } else {
        data = await getProperties();
      }
      setProperties(data);
      setError(null);
    } catch (err) {
      setError('Failed to load properties. Please try again later.');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadProperties();
  }, []);

  const handleSearch = (filters) => {
    loadProperties(filters);
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this property?')) {
      try {
        await deleteProperty(id);
        loadProperties();
      } catch (err) {
        setError('Failed to delete property. Please try again later.');
      }
    }
  };

  if (loading) {
    return <div className="text-center py-10">Loading properties...</div>;
  }

  return (
    <div>
      <h1 className="text-2xl font-bold mb-6">Available Properties</h1>
      <SearchFilter onSearch={handleSearch} />
      
      {error && (
        <div className="bg-red-100 text-red-700 p-4 rounded mb-4">
          {error}
        </div>
      )}
      
      {properties.length === 0 ? (
        <div className="text-center py-10 text-gray-500">
          No properties found. Try adjusting your search filters.
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {properties.map(property => (
            <PropertyCard 
              key={property.property_id} 
              property={property} 
              onNavigate={onNavigate}
              onDelete={() => handleDelete(property.property_id)}
            />
          ))}
        </div>
      )}
    </div>
  );
};

export default PropertyList;
